// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // bound amount to avoid overflow in msg.value conversion
        amount = bound(amount, 0, 10 ether);
        vm.deal(address(this), amount);
        bool ok;
        try c.fallback{value: amount}() { ok = true; } catch { ok = false; }
        // Reference C: fallback only succeeds when amount == 10 ether, always reverts otherwise.
        // Buggy M: fallback only succeeds when amount == 0, always reverts otherwise.
        // The property: for any amount, the call success (ok==true) implies amount == 10 ether.
        // This holds for P (it never succeeds unless amount==10 ether), but in M it fails for amount == 10 ether (where it reverts).
        assertTrue(!ok || amount == 10 ether);
    }
}

