pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNumber) public {
        // Ensure timestamps are admissible (>= previous, first call requires timestamp1 > 0 initially)
        vm.assume(timestamp2 >= timestamp1);
        vm.assume(timestamp1 > 0);
        // Limit to reasonable bounds to speed up fuzzing
        bound(timestamp1, 1, 2**48);
        bound(timestamp2, timestamp1, 2**48);
        bound(blockNumber, 0, 2**48 - 15);

        // Deal to a test actor
        address actor = makeAddr("actor");
        vm.deal(actor, 20 ether);

        // First call: timestamp1
        vm.warp(timestamp1);
        vm.roll(blockNumber);
        vm.prank(actor);
        c.f{value: 10 ether}();
        uint256 past1 = c.pastBlockTime();

        // Second call: timestamp2 (>= timestamp1)
        // Setup: warp to timestamp2, set block number to something, deal again if needed
        vm.warp(timestamp2);
        vm.roll(blockNumber + 1); // any block number, not necessarily %15==0; but must allow call.
        vm.deal(actor, 20 ether); // ensure enough balance
        vm.prank(actor);
        c.f{value: 10 ether}();
        uint256 past2 = c.pastBlockTime();

        // Property: pastBlockTime after second call MUST be strictly greater than after first call.
        // Reference contract always satisfies this because require(block.timestamp > pastBlockTime),
        // and timestamp2 >= timestamp1, so past2 > past1.
        // Buggy contract violates for timestamp2 == timestamp1: then past2 == timestamp1 == past1, failing strict increase.
        assertTrue(past2 > past1);
    }
}

