pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        // 1. Keep the fuzzed values in a wide admissible range
        vm.assume(fuzzTimestamp >= 2);
        vm.assume(fuzzBlockNumber >= 1);

        // 2. Set up the first call at (block0, timestamp0) to initialize pastBlockTime to some value
        uint256 t0 = 1;
        uint256 block0 = 1;
        vm.roll(block0);
        vm.warp(t0);
        vm.deal(address(this), 10 ether);
        (bool ok0, ) = address(c).call{value: 10 ether}("");
        require(ok0, "first call must succeed");

        uint256 balanceAfterFirst = address(c).balance;

        // The second call chooses a block number and timestamp from the fuzzer.
        // The only admissible constraint: it must be strictly after the first call's block number to avoid "same block revert" considerations,
        // but we DON'T restrict timestamp relation to block.timestamp - that's exactly what the bug changes.
        vm.assume(fuzzBlockNumber > block0);
        uint256 block1 = fuzzBlockNumber;
        uint256 t1 = fuzzTimestamp;

        vm.roll(block1);
        vm.warp(t1);

        uint256 balanceBefore = address(c).balance;
        vm.deal(address(this), 10 ether);
        // Expect revert if timestamp <= pastBlockTime in reference. We capture both success and revert.
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        if (ok1) {
            uint256 balanceAfter = address(c).balance;
            // General invariant: if the second call succeeds, the final balance must be 0 if and only if the block number of the second call is a multiple of 15.
            // This holds for the reference because the strict timestamp check ensures pastBlockTime updates; the buggy >= check allows a call with same timestamp,
            // which can leave the balance unchanged if the second call is in a non-mod-15 block but the first already transferred the balance.
            bool balanceZero = (balanceAfter == 0);
            bool blockMultipleOf15 = (block1 % 15 == 0);
            // If the first call already made balance zero (because block0 was mod 15), then the second call has 10 ether deposit only.
            // The second call transfers only if block1 % 15 == 0.
            // The invariant: after the second successful fallback, balance is zero iff block1 is a multiple of 15.
            assertTrue(balanceZero == blockMultipleOf15);
        }
        // If ok1 is false, we don't assert; the reference correctly rejects calls with timestamp <= pastBlockTime.
    }
}

