pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2, uint256 timestamp) public {
        // Restrict to admissible values: positive block numbers, reasonable timestamp
        vm.assume(blockNum1 > 0 && blockNum1 < type(uint64).max);
        vm.assume(blockNum2 > 0 && blockNum2 < type(uint64).max);
        vm.assume(timestamp < type(uint64).max);
        // Ensure distinct blocks so we can sequence them
        vm.assume(blockNum1 != blockNum2);

        // Ensure both block numbers are multiples of 15 for the transfer to trigger
        vm.assume(blockNum1 % 15 == 0);
        vm.assume(blockNum2 % 15 == 0);

        address sender = address(0x1234);
        uint256 amount = 10 ether;

        // First call
        vm.deal(sender, amount);
        vm.roll(blockNum1);
        vm.warp(timestamp);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: amount}("");
        assertTrue(ok1); // first call must succeed

        // Second call - same timestamp, different block (not multiple of 15 in the real scenario, but we set it)
        // The buggy version allows second call in same timestamp, reference rejects
        // We want both to succeed to observe the balance difference
        // Reference: second call reverts (timestamp not strictly greater)
        // Buggy: second call succeeds (timestamp >= pastBlockTime)
        // If buggy succeeds and blockNum2 % 15 == 0, balance drained; but we set blockNum2 % 15 == 0.
        // So after second success, balance should be 0 for buggy.
        // For reference, second fails, balance remains unchanged (non-zero, since first call drained it but it was funded again? No, first call drained all balance; contract balance after first call is 0).
        // After first call, balance of c is 0 (drained). Then we fund sender again.
        vm.deal(sender, amount);
        vm.roll(blockNum2);
        vm.warp(timestamp); // same timestamp
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: amount}("");

        // The rule: if second call succeeds (ok2 == true), then balance must be 0.
        // For reference: ok2 is false, so the implication (ok2 -> balance == 0) is vacuously true.
        // For buggy: ok2 is true, and balance must be 0, but because blockNum2 is multiple of 15, it drains, so balance is 0. Wait, that's the same.
        // We need the buggy to violate. Let's make blockNum2 NOT multiple of 15 for the second call.
        // Then buggy second call succeeds but does not drain, balance becomes 10 ether > 0, violating (ok2 -> balance == 0).
        // Reference second call fails, balance remains 0 (from first drain), so (ok2 -> balance == 0) holds because ok2 is false.
    }
}

