import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 senderSeed, uint256 blockNumber, uint256 startTimestamp) public {
        address actor = address(uint160(senderSeed));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(blockNumber > 0);
        // Restrict timestamp to avoid overflow in solidity
        vm.assume(startTimestamp < type(uint256).max - 1);

        // Set initial state: warp to a known past timestamp and roll to previous block
        vm.warp(startTimestamp);
        vm.roll(blockNumber - 1);

        // First call to set pastBlockTime to startTimestamp
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "first call failed");

        // Advance time and go to the target block
        vm.warp(startTimestamp + 1);
        vm.roll(blockNumber);

        // Record pre-call balance
        uint256 balanceBefore = address(c).balance;

        // Second call with exactly 10 ether
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (success, ) = address(c).call{value: 10 ether}("");
        require(success, "second call failed");

        uint256 balanceAfter = address(c).balance;

        // For reference contract: balance becomes 0 iff block.number % 15 == 0.
        // For buggy contract:  balance becomes 0 iff block.number % 15 != 0.
        // The general invariant is:
        // (balanceAfter == 0) == (block.number % 15 == 0)
        assertTrue((balanceAfter == 0) == (blockNumber % 15 == 0));
    }
}

