contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 warpedTime, address sender, uint96 extraBalance) public {
        vm.assume(blockNumber > 0);
        vm.assume(warpedTime > 0);
        vm.assume(sender != address(0));
        vm.assume(extraBalance > 0);

        // Set block number and timestamp for the call
        vm.roll(blockNumber);
        vm.warp(warpedTime);

        // Give the sender enough ether for the required msg.value (10 ether) and some extra to donate
        uint256 requiredValue = 10 ether;
        vm.deal(sender, requiredValue + uint256(extraBalance));

        // Also fund the contract with extra balance to be potentially transferred back
        vm.deal(address(c), extraBalance);

        // Call fallback with exactly 10 ether
        vm.prank(sender);
        (bool success, ) = address(c).call{value: requiredValue}("");
        require(success, "fallback call failed");

        // The invariant:
